import json


class RestAPI:
    def __init__(self, database=None):
        self.database = database if database is not None else {"users": []}

    def get(self, url, payload=None):
        if url == "/users":
            users = self._get_users(payload)
            return json.dumps({"users": users})
        raise ValueError(f"Unknown URL: {url}")

    def post(self, url, payload=None):
        if url == "/add":
            return self._add_user(payload)
        if url == "/iou":
            return self._create_iou(payload)
        raise ValueError(f"Unknown URL: {url}")

    def _get_users(self, payload=None):
        users = self.database["users"]
        if payload:
            names = json.loads(payload).get("users", [])
            users = [u for u in users if u["name"] in names]
        return sorted(users, key=lambda u: u["name"])

    def _add_user(self, payload):
        name = json.loads(payload)["user"]
        user = {"name": name, "owes": {}, "owed_by": {}, "balance": 0.0}
        self.database["users"].append(user)
        return json.dumps(user)

    def _create_iou(self, payload):
        data = json.loads(payload)
        lender = self._find_user(data["lender"])
        borrower = self._find_user(data["borrower"])
        amount = data["amount"]

        # Net the new loan against any existing debt between the two.
        existing = lender["owes"].get(borrower["name"], 0.0)
        diff = amount - existing
        del lender["owes"][borrower["name"]]
        del borrower["owed_by"][lender["name"]]

        if diff > 0:
            borrower["owes"][lender["name"]] = borrower["owes"].get(
                lender["name"], 0.0
            ) + diff
            lender["owed_by"][borrower["name"]] = lender["owed_by"].get(
                borrower["name"], 0.0
            ) + diff
        elif diff < 0:
            lender["owes"][borrower["name"]] = lender["owes"].get(
                borrower["name"], 0.0
            ) - diff
            borrower["owed_by"][lender["name"]] = borrower["owed_by"].get(
                lender["name"], 0.0
            ) - diff

        self._rebalance(lender)
        self._rebalance(borrower)

        users = sorted([lender, borrower], key=lambda u: u["name"])
        return json.dumps({"users": users})

    def _find_user(self, name):
        for user in self.database["users"]:
            if user["name"] == name:
                return user
        raise ValueError(f"User not found: {name}")

    def _rebalance(self, user):
        user["balance"] = sum(user["owed_by"].values()) - sum(user["owes"].values())

